async function dismiss(sdk: any) {
  const state = sdk.getState();
  if (!state) return;
  if (state.dialog?.isOpen) {
    const opts = state.dialog.options ?? [];
    const yes = opts.find((o: any) => /yes, ok/i.test(o.text));
    if (yes) await sdk.sendClickDialog(yes.index);
    else if (opts.length <= 1) await sdk.sendClickDialog(opts[0]?.index ?? 0);
    await sdk.waitForTicks(1);
    return;
  }
  if (state.interface?.isOpen && !state.shop?.isOpen && !state.bank?.isOpen) {
    await sdk.sendCloseModal();
    await sdk.waitForTicks(1);
  }
}

