  if (stunned) await sdk.waitForTicks(6);
}
return { gp, pos: [sdk.getState()?.player?.worldX, sdk.getState()?.player?.worldZ] };

const sword = sdk.findInventoryItem(/bronze sword/i);
const shield = sdk.findInventoryItem(/wooden shield/i);
if (sword) await bot.equipItem(sword);
if (shield) await bot.equipItem(shield);
const end = Date.now() + 15000;
while (Date.now() < end) {
  const gp = sdk.findInventoryItem(/coins/i)?.count || 0;
  if (gp >= 90) break;
  if (sdk.getDialog()?.isOpen) { await sdk.sendClickDialog(0); await sdk.waitForTicks(1); continue; }
  const man = sdk.getState()?.nearbyNpcs?.find(n => /^man$/i.test(n.name));
  if (!man) break;
  try { await bot.pickpocketNpc(man); } catch (e) {}
  if ((sdk.getState()?.gameMessages||[]).slice(-1).some(m => /stunned/i.test(m.text))) await sdk.waitForTicks(6);
}
return { gp: sdk.findInventoryItem(/coins/i)?.count, equip: sdk.getState()?.equipment };

const r = await bot.walkTo(3014, 3205);
const p = sdk.getState()?.player;
const npcs = sdk.getState()?.nearbyNpcs?.filter(n => /wydin|seaman|captain/i.test(n.name)).map(n => `${n.name} (${n.x},${n.z}) d=${n.distance} opts=${n.options}`);
return { pos: [p?.worldX, p?.worldZ], npcs, hp: sdk.getSkill('hitpoints')?.level };
